-- ============================================================
-- MD Portal — Migration 007: Phase 5 (HR + Attendance) + invite-code signup
-- Idempotent: safe to run repeatedly in Supabase SQL Editor.
--
-- AFTER running this, change two Supabase settings (see README):
--   Authentication → Sign In / Up →
--     1. ENABLE  "Allow new users to sign up"
--     2. DISABLE "Confirm email"
-- Signup stays safe: the database itself rejects any signup that
-- doesn't carry a valid, unused invite code generated by an admin.
-- ============================================================

-- ---------- 1. Invite codes ----------
create table if not exists invite_codes (
  code text primary key,
  role user_role not null default 'employee',
  department text,
  created_by uuid references profiles(id) default auth.uid(),
  created_at timestamptz not null default now(),
  used_by uuid references profiles(id),
  used_at timestamptz
);
alter table invite_codes enable row level security;
drop policy if exists invites_admin on invite_codes;
create policy invites_admin on invite_codes for all to authenticated
  using (public.is_admin()) with check (public.is_admin());

-- Pre-check for the signup page (so it can show a clear error before
-- creating anything). Returns true only for a valid, unused code.
create or replace function public.check_invite(p_code text)
returns boolean language sql stable security definer set search_path = public
as $$
  select exists (
    select 1 from invite_codes
    where code = upper(trim(p_code)) and used_by is null
  )
$$;

-- The real gate: a new auth user is allowed only when
--   (a) it carries a valid, unused invite code (self-signup), or
--   (b) it was created by the admin from the Supabase dashboard
--       with "Auto Confirm User" ticked (email_confirmed_at set).
create or replace function public.handle_new_user()
returns trigger
language plpgsql security definer set search_path = public
as $$
declare
  v_code text := upper(trim(coalesce(new.raw_user_meta_data->>'invite_code', '')));
  v_role user_role;
  v_dept text;
begin
  if v_code <> '' then
    update invite_codes
      set used_by = new.id, used_at = now()
      where code = v_code and used_by is null
      returning role, department into v_role, v_dept;
    if not found then
      raise exception 'Invalid or already-used invite code';
    end if;
    insert into public.profiles (id, full_name, role, department)
    values (
      new.id,
      coalesce(new.raw_user_meta_data->>'full_name', split_part(new.email,'@',1)),
      v_role,
      v_dept
    );
  elsif new.email_confirmed_at is not null then
    -- created by the admin in the Supabase dashboard (Auto Confirm ticked)
    insert into public.profiles (id, full_name)
    values (new.id, coalesce(new.raw_user_meta_data->>'full_name', split_part(new.email,'@',1)));
  else
    raise exception 'Sign-up requires an invite code';
  end if;
  return new;
end;
$$;

-- ---------- 2. Sick-leave balance (21 annual + 7 sick, §12.3) ----------
alter table leave_balances
  add column if not exists sick_total numeric(5,1) not null default 7,
  add column if not exists sick_used numeric(5,1) not null default 0;

-- Employees may cancel (delete) their own still-pending requests.
drop policy if exists leave_delete_own on leave_requests;
create policy leave_delete_own on leave_requests for delete to authenticated
  using (employee_id = auth.uid() and status = 'pending');

-- ---------- 3. Leave decision (the ONLY path that touches balances) ----------
-- annual + casual deduct from the annual balance; sick from the sick balance;
-- unpaid + mission deduct nothing. Exceptions beyond the balance can be
-- approved only by admin (GM/VP — §12.3); HR is blocked at the limit.
create or replace function public.decide_leave(
  p_request_id uuid,
  p_approve boolean,
  p_comment text default null
) returns void
language plpgsql security definer set search_path = public
as $$
declare
  v_req leave_requests%rowtype;
  v_days numeric;
  v_year int;
  v_total numeric;
  v_used numeric;
begin
  if public.my_role() not in ('admin','hr') then
    raise exception 'Only HR or admin can decide leave requests';
  end if;

  select * into v_req from leave_requests where id = p_request_id for update;
  if not found then
    raise exception 'Leave request not found';
  end if;
  if v_req.status <> 'pending' then
    raise exception 'This request was already decided';
  end if;

  if not p_approve then
    update leave_requests
      set status = 'rejected', reviewed_by = auth.uid(), review_comment = p_comment
      where id = p_request_id;
    return;
  end if;

  v_days := case when v_req.half_day then 0.5
                 else (v_req.end_date - v_req.start_date + 1) end;
  v_year := extract(year from v_req.start_date)::int;

  insert into leave_balances (employee_id, year)
    values (v_req.employee_id, v_year)
    on conflict (employee_id, year) do nothing;

  if v_req.type in ('annual','casual') then
    select annual_total, annual_used into v_total, v_used
      from leave_balances where employee_id = v_req.employee_id and year = v_year for update;
    if v_used + v_days > v_total and not public.is_admin() then
      raise exception 'Exceeds the annual balance — only the GM/VP can approve an exception';
    end if;
    update leave_balances set annual_used = annual_used + v_days
      where employee_id = v_req.employee_id and year = v_year;
  elsif v_req.type = 'sick' then
    select sick_total, sick_used into v_total, v_used
      from leave_balances where employee_id = v_req.employee_id and year = v_year for update;
    if v_used + v_days > v_total and not public.is_admin() then
      raise exception 'Exceeds the sick balance — only the GM/VP can approve an exception';
    end if;
    update leave_balances set sick_used = sick_used + v_days
      where employee_id = v_req.employee_id and year = v_year;
  end if;  -- unpaid / mission: no deduction

  update leave_requests
    set status = 'approved', reviewed_by = auth.uid(), review_comment = p_comment
    where id = p_request_id;
end;
$$;

revoke execute on function public.decide_leave(uuid, boolean, text) from anon;

-- ---------- 4. A logged visit appears in the hospital's CRM feed ----------
create or replace function public.log_visit_activity()
returns trigger language plpgsql security definer set search_path = public
as $$
begin
  insert into activities (hospital_id, visit_id, type, body, created_by)
  values (new.hospital_id, new.id, 'visit',
          new.purpose::text || coalesce(' — ' || nullif(new.notes,''), ''),
          new.rep_id);
  return new;
end;
$$;
drop trigger if exists trg_visit_activity on visits;
create trigger trg_visit_activity
  after insert on visits
  for each row execute function public.log_visit_activity();

-- ---------- 5. Storage bucket for leave attachments ----------
insert into storage.buckets (id, name, public)
  values ('leave-docs', 'leave-docs', false)
  on conflict (id) do nothing;

drop policy if exists "leave docs upload own" on storage.objects;
create policy "leave docs upload own" on storage.objects for insert to authenticated
  with check (bucket_id = 'leave-docs' and (storage.foldername(name))[1] = auth.uid()::text);

drop policy if exists "leave docs read" on storage.objects;
create policy "leave docs read" on storage.objects for select to authenticated
  using (bucket_id = 'leave-docs'
         and ((storage.foldername(name))[1] = auth.uid()::text
              or public.my_role() in ('admin','hr')));

notify pgrst, 'reload schema';
